package dev.trentdb.storage;import dev.trentdb.storage.format.StorageFormatException;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class DuckDbPrimitivePayloadReaderTest{@TempDir Path d;@Test void readsLittleEndianIntegerAndValidity(){var p=d.resolve("p");try(var w=SingleFileBlockManager.create(p,new byte[16])){byte[] a=new byte[w.usableBlockSize()],v=new byte[w.usableBlockSize()];a[0]=2;a[8]=9;v[0]=5;w.writeBlock(0,a);w.writeBlock(1,v);}try(var m=SingleFileBlockManager.openMetadataReadOnly(p)){var r=new DuckDbPrimitivePayloadReader(m);assertEquals(Arrays.asList(2L,null,9L),r.read(DuckDbTableCreateInfo.ScalarLogicalType.INTEGER,s(3,0,0,2,9),s(3,1,0,0,0)));}}@Test void rejectsStatsAndVectorBoundary(){var p=d.resolve("q");try(var w=SingleFileBlockManager.create(p,new byte[16])){w.writeBlock(0,new byte[w.usableBlockSize()]);}try(var m=SingleFileBlockManager.openMetadataReadOnly(p)){var r=new DuckDbPrimitivePayloadReader(m);assertThrows(StorageFormatException.class,()->r.read(DuckDbTableCreateInfo.ScalarLogicalType.INTEGER,s(2049,0,0,0,0),null));assertThrows(StorageFormatException.class,()->r.read(DuckDbTableCreateInfo.ScalarLogicalType.INTEGER,s(1,0,0,1,1),null));}}private static DuckDbPrimitiveColumnMetadata.Segment s(long n,long b,long o,long min,long max){return new DuckDbPrimitiveColumnMetadata.Segment(n,new DuckDbPrimitiveColumnMetadata.BlockPointer(b,o),1,new DuckDbPrimitiveColumnMetadata.Statistics(false,true,n,OptionalLong.of(min),OptionalLong.of(max)));}}
